import{_ as a,o as n,c as t,a3 as p}from"./chunks/framework.Dz5Q8p4s.js";const o=JSON.parse('{"title":"GAIA-1: A Generative World Model for Autonomous Driving","description":"","frontmatter":{"title":"GAIA-1: A Generative World Model for Autonomous Driving","arxiv":"2309.17080","date":"2023-09-29","authors":"Anthony Hu, Lloyd Russell, Hudson Yeo, Zak Murez, George Fedoseev, Alex Kendall, Jamie Shotton, Gianluca Corrado","categories":"cs.CV, cs.AI, cs.RO","topics":"世界模型, 自动驾驶, 自回归生成","outline":[2,2]},"headers":[],"relativePath":"papers/2309.17080.md","filePath":"papers/2309.17080.md","lastUpdated":null}'),e={name:"papers/2309.17080.md"};function l(m,s,r,i,c,g){return n(),t("div",null,[...s[0]||(s[0]=[p('<h1 id="gaia-1-a-generative-world-model-for-autonomous-driving" tabindex="-1">GAIA-1: A Generative World Model for Autonomous Driving <a class="header-anchor" href="#gaia-1-a-generative-world-model-for-autonomous-driving" aria-label="Permalink to &quot;GAIA-1: A Generative World Model for Autonomous Driving&quot;">​</a></h1><table tabindex="0"><thead><tr><th>项</th><th>内容</th></tr></thead><tbody><tr><td><strong>arXiv</strong></td><td><a href="https://arxiv.org/abs/2309.17080" target="_blank" rel="noreferrer">2309.17080</a></td></tr><tr><td><strong>提交日期</strong></td><td>2023-09-29</td></tr><tr><td><strong>作者</strong></td><td>Anthony Hu, Lloyd Russell, Hudson Yeo, Zak Murez, George Fedoseev, Alex Kendall, Jamie Shotton, Gianluca Corrado（Wayve）</td></tr><tr><td><strong>分类</strong></td><td>cs.CV, cs.AI, cs.RO（Technical Report）</td></tr><tr><td><strong>一句话</strong></td><td>把驾驶世界建模拆成「离散 token 上的自回归世界模型 + 视频扩散解码器」两段，前者用 next-token prediction 学动力学并吃到 LLM 式 scaling law，后者只负责把 token 还原成高帧率真实画面。</td></tr></tbody></table><blockquote><p><strong>所属教程</strong>：<a href="/notes/tutorials/world-models">世界模型</a></p></blockquote><h2 id="§-1-—-研究问题与重要性" tabindex="-1">§ 1 — 研究问题与重要性 <a class="header-anchor" href="#§-1-—-研究问题与重要性" aria-label="Permalink to &quot;§ 1 — 研究问题与重要性&quot;">​</a></h2><p>自动驾驶的核心难题之一是<strong>预测世界在响应本车动作后会如何演化</strong>——能准确预测未来，车才能提前规划。价值不止于预测本身：足够好的生成式世界模型可以当神经模拟器用，无限量生成数据（包括对抗性样本）来训练与验证系统，还能在世界模型内部做基于模型的策略学习与闭环探索。在 2023 年这个时间点，把 LLM 的 scaling 范式搬到驾驶世界建模并证明 scaling law 同样成立，本身就是一个重要判断。</p><h2 id="§-2-—-前人工作与不足" tabindex="-1">§ 2 — 前人工作与不足 <a class="header-anchor" href="#§-2-—-前人工作与不足" aria-label="Permalink to &quot;§ 2 — 前人工作与不足&quot;">​</a></h2><p><strong>世界模型一侧</strong>已在仿真控制任务（MuZero、Dreamer 系列）与真实机器人任务（DayDreamer）上成功过。作者指出两个具体限制：这些方法<strong>常依赖难以规模化获取的标注数据</strong>，且在仿真数据上工作的模型未必能捕捉真实世界的复杂度；更关键的是由于使用低维表征，它们<strong>难以生成高保真的未来样本</strong>。<strong>生成式视频一侧</strong>已借自监督从海量真实数据学出高度逼真的样本（Imagen Video、Gen-1 一类），但作者点出持续存在的困难：<strong>难以学到一个能捕捉「对未来事件的期望」的表征</strong>。GAIA-1 的定位是两条线的交点，解法是把两者<strong>物理上分开</strong>——世界模型推理场景的高层组成与动力学，扩散解码器把 latent 翻回带真实细节的高质量视频。</p><h2 id="§-3-—-重建作者的思考路径" tabindex="-1">§ 3 — 重建作者的思考路径 <a class="header-anchor" href="#§-3-—-重建作者的思考路径" aria-label="Permalink to &quot;§ 3 — 重建作者的思考路径&quot;">​</a></h2><p>从 2023 年的两个既有事实出发：LLM 已证明「next-token prediction 加规模」是一条可预测地变强的路，有 scaling law 就能用小模型预测大模型性能；视频扩散已证明能产出时序一致的高分辨率画面。于是问题变成：能否把驾驶的未来预测<strong>改写成 next-token prediction</strong>？障碍是视频连续高维，需要图像 tokenizer；但直接用 VQ-GAN 会让 token 被高频信号主导，而高频信号会大幅拖慢世界模型的学习。顺着这个问题，自然的解法是<strong>把压缩引导向语义</strong>：DINO 是已知含丰富语义的自监督模型，那就用余弦相似度让量化后的特征回归 DINO 特征。最后一个障碍是单帧训练的解码器缺时序一致性、而世界模型必须降采样帧率——两者可由同一个多任务视频扩散解码器解决，它既做高分辨率渲染又做时序超分。</p><h2 id="§-4-—-核心-intuition" tabindex="-1">§ 4 — 核心 Intuition <a class="header-anchor" href="#§-4-—-核心-intuition" aria-label="Permalink to &quot;§ 4 — 核心 Intuition&quot;">​</a></h2><p>把「预测未来」和「画得好看」拆开，让它们各自吃各自的 scaling。世界模型在一个被 DINO 语义引导过的离散 token 空间里做 next-token prediction，因此被迫学的是场景的高层结构与动力学而非像素级高频细节；扩散解码器完全不必操心未来会发生什么，只需把给定 token 渲染成时序一致的高帧率视频。让先前方法失效的是「低维表征保真度不够」与「高保真生成学不到未来期望」这对矛盾，而这个分工同时绕开了两者。</p><h2 id="§-5-—-具体方法与完整-pipeline" tabindex="-1">§ 5 — 具体方法与完整 Pipeline <a class="header-anchor" href="#§-5-—-具体方法与完整-pipeline" aria-label="Permalink to &quot;§ 5 — 具体方法与完整 Pipeline&quot;">​</a></h2><p>以「给一段行车视频作 prompt、然后强制本车右转」为例。三种模态被编码到共享的 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6944em;"></span><span class="mord mathnormal">d</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.6444em;"></span><span class="mord">4096</span></span></span></span> 维空间：图像每帧离散化为 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.4306em;"></span><span class="mord mathnormal">n</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.6444em;"></span><span class="mord">576</span></span></span></span> 个 token，文本用 T5-large 编码为每步 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.4306em;"></span><span class="mord mathnormal">m</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.6444em;"></span><span class="mord">32</span></span></span></span> 个 token，动作是速度与曲率两个标量；每步 token 按 <strong>text - image - action</strong> 交错。<strong>图像 tokenizer</strong>（0.3B）是全卷积 2D U-Net 离散自编码器，输入 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.7278em;vertical-align:-0.0833em;"></span><span class="mord">288</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">×</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:0.6444em;"></span><span class="mord">512</span></span></span></span>，下采样因子 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord mathnormal" style="margin-right:0.0278em;">D</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.6444em;"></span><span class="mord">16</span></span></span></span>，每帧 576 个 token，码本 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord mathnormal" style="margin-right:0.0715em;">K</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.6444em;"></span><span class="mord">8192</span></span></span></span>，比特压缩率约 470 倍；损失含图像重建、量化损失，以及<strong>归纳偏置损失</strong>（量化后特征用余弦相似度对齐 DINO）；最终只用编码器，因为解码器是单图训练的。</p><p><strong>世界模型</strong>（6.5B）是因果掩码自回归 transformer，训练时随机 dropout 条件 token 使同一模型支持无条件、动作条件、文本条件生成（比例 20% / 40% / 40%）；为控制序列长度，视频从 25 Hz 降到 6.25 Hz，<span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord mathnormal" style="margin-right:0.1389em;">T</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.6444em;"></span><span class="mord">26</span></span></span></span> 对应 4 秒，总长 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.7278em;vertical-align:-0.0833em;"></span><span class="mord">26</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">×</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:0.6444em;"></span><span class="mord">610</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.6444em;"></span><span class="mord">15860</span></span></span></span>。<strong>视频解码器</strong>（2.6B）是空间与时间 attention 分解的 3D U-Net，单模型等概率联合训练图像生成、视频生成、自回归解码、视频插值四种任务并靠掩码区分。<strong>推理</strong>侧用 top-k 采样（<span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6944em;"></span><span class="mord mathnormal" style="margin-right:0.0315em;">k</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.6444em;"></span><span class="mord">50</span></span></span></span>）：困惑度分析显示 argmax 会陷入重复循环、从完整分布采样又会从不可靠尾部取到 token 把模型带出分布；文本条件用 classifier-free guidance 且 scale 需<strong>同时在 token 与帧两个维度上排程</strong>；解码侧先解最后 7 帧然后<strong>反向</strong>自回归解码（从末尾往前解能让物体更稳定、地平线闪烁更少），再做 6.25→12.5→25 Hz 的时域超分。</p><h2 id="§-6-—-核心数学推导" tabindex="-1">§ 6 — 核心数学推导 <a class="header-anchor" href="#§-6-—-核心数学推导" aria-label="Permalink to &quot;§ 6 — 核心数学推导&quot;">​</a></h2><p>世界模型的训练目标是条件自回归似然：</p><p class="katex-block"><span class="katex-display"><span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.8333em;vertical-align:-0.15em;"></span><span class="mord"><span class="mord mathnormal">L</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3361em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord text mtight"><span class="mord mtight">world model</span></span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:3.106em;vertical-align:-1.2777em;"></span><span class="mord">−</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mop op-limits"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:1.8283em;"><span style="top:-1.8829em;margin-left:0em;"><span class="pstrut" style="height:3.05em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mathnormal mtight">t</span><span class="mrel mtight">=</span><span class="mord mtight">1</span></span></span></span><span style="top:-3.05em;"><span class="pstrut" style="height:3.05em;"></span><span><span class="mop op-symbol large-op">∑</span></span></span><span style="top:-4.3em;margin-left:0em;"><span class="pstrut" style="height:3.05em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mathnormal mtight" style="margin-right:0.1389em;">T</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:1.2671em;"><span></span></span></span></span></span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mop op-limits"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:1.6514em;"><span style="top:-1.8723em;margin-left:0em;"><span class="pstrut" style="height:3.05em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mathnormal mtight">i</span><span class="mrel mtight">=</span><span class="mord mtight">1</span></span></span></span><span style="top:-3.05em;"><span class="pstrut" style="height:3.05em;"></span><span><span class="mop op-symbol large-op">∑</span></span></span><span style="top:-4.3em;margin-left:0em;"><span class="pstrut" style="height:3.05em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mathnormal mtight">n</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:1.2777em;"><span></span></span></span></span></span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mop">lo<span style="margin-right:0.0139em;">g</span></span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord mathnormal">p</span><span class="mord"><span class="delimsizing size1">(</span></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.044em;">z</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3117em;"><span style="top:-2.55em;margin-left:-0.044em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mathnormal mtight">t</span><span class="mpunct mtight">,</span><span class="mord mathnormal mtight">i</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.2861em;"><span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">∣</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:1.2em;vertical-align:-0.35em;"></span><span class="mord"><span class="mord mathbf">z</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.2806em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mrel mtight">&lt;</span><span class="mord mathnormal mtight">t</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.1774em;"><span></span></span></span></span></span></span><span class="mpunct">,</span><span class="mspace"> </span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.044em;">z</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3117em;"><span style="top:-2.55em;margin-left:-0.044em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mathnormal mtight">t</span><span class="mpunct mtight">,</span><span class="mord mathnormal mtight" style="margin-right:0.0572em;">j</span><span class="mrel mtight">&lt;</span><span class="mord mathnormal mtight">i</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.2861em;"><span></span></span></span></span></span></span><span class="mpunct">,</span><span class="mspace"> </span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord"><span class="mord mathbf">c</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.2952em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mrel mtight">≤</span><span class="mord mathnormal mtight">t</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.2452em;"><span></span></span></span></span></span></span><span class="mpunct">,</span><span class="mspace"> </span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord"><span class="mord mathbf">a</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.2806em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mrel mtight">&lt;</span><span class="mord mathnormal mtight">t</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.1774em;"><span></span></span></span></span></span></span><span class="mord"><span class="delimsizing size1">)</span></span></span></span></span></span></p><p>两个细节值得为数学基础较弱的读者点明。其一，条件里既有此前所有帧，也有<strong>当前帧内已生成的 token</strong> <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.7167em;vertical-align:-0.2861em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.044em;">z</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3117em;"><span style="top:-2.55em;margin-left:-0.044em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mathnormal mtight">t</span><span class="mpunct mtight">,</span><span class="mord mathnormal mtight" style="margin-right:0.0572em;">j</span><span class="mrel mtight">&lt;</span><span class="mord mathnormal mtight">i</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.2861em;"><span></span></span></span></span></span></span></span></span></span>——帧内也是自回归的，一帧要走 576 次前向。其二，文本用 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6896em;vertical-align:-0.2452em;"></span><span class="mord"><span class="mord mathbf">c</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.2952em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mrel mtight">≤</span><span class="mord mathnormal mtight">t</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.2452em;"><span></span></span></span></span></span></span></span></span></span> 而动作用 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6218em;vertical-align:-0.1774em;"></span><span class="mord"><span class="mord mathbf">a</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.2806em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mrel mtight">&lt;</span><span class="mord mathnormal mtight">t</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.1774em;"><span></span></span></span></span></span></span></span></span></span>：动作严格用过去的，这保证「给定新动作预测未来」在推理时是良定义的干预而非偷看答案。</p><p>视频解码器用 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.4444em;"></span><span class="mord mathbf" style="margin-right:0.016em;">v</span></span></span></span>-参数化的去噪目标（作者选它因为避免了不自然色偏并保持长程一致性）。文本引导写作 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.8444em;vertical-align:-0.15em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0197em;">l</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3361em;"><span style="top:-2.55em;margin-left:-0.0197em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord text mtight"><span class="mord mtight">final</span></span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mopen">(</span><span class="mord">1</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">+</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord mathnormal">t</span><span class="mclose">)</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0197em;">l</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3361em;"><span style="top:-2.55em;margin-left:-0.0197em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord text mtight"><span class="mord mtight">cond</span></span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">−</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:0.8444em;vertical-align:-0.15em;"></span><span class="mord mathnormal">t</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0197em;">l</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3361em;"><span style="top:-2.55em;margin-left:-0.0197em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord text mtight"><span class="mord mtight">uncond</span></span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span></span></span></span>，直觉是把「条件下的偏好」与「无条件偏好」之差放大 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6151em;"></span><span class="mord mathnormal">t</span></span></span></span> 倍以增强对齐，代价是降低多样性——这正是需要在两个维度排程的原因。解码时还有一个混合 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.8179em;vertical-align:-0.15em;"></span><span class="mord"><span class="mord accent"><span class="vlist-t"><span class="vlist-r"><span class="vlist" style="height:0.6679em;"><span style="top:-3em;"><span class="pstrut" style="height:3em;"></span><span class="mord mathnormal">ϵ</span></span><span style="top:-3.35em;"><span class="pstrut" style="height:3em;"></span><span class="accent-body" style="left:-0.1944em;"><span class="mord">~</span></span></span></span></span></span></span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3361em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight" style="margin-right:0.0278em;">θ</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.9475em;vertical-align:-0.2831em;"></span><span class="mord mathnormal" style="margin-right:0.0269em;">w</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord"><span class="mord mathnormal">ϵ</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.6644em;"><span style="top:-2.4169em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight" style="margin-right:0.0278em;">θ</span></span></span><span style="top:-3.063em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mathnormal mtight" style="margin-right:0.0359em;">π</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.2831em;"><span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">+</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mopen">(</span><span class="mord">1</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">−</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord mathnormal" style="margin-right:0.0269em;">w</span><span class="mclose">)</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord"><span class="mord mathnormal">ϵ</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3361em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight" style="margin-right:0.0278em;">θ</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span></span></span></span>，前者把每帧当独立图像去噪、后者把序列当视频联合去噪（实现上即开关时间层），以 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.625em;vertical-align:-0.1944em;"></span><span class="mord mathnormal">p</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.6444em;"></span><span class="mord">0.25</span></span></span></span>、<span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.4306em;"></span><span class="mord mathnormal" style="margin-right:0.0269em;">w</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.6444em;"></span><span class="mord">0.5</span></span></span></span> 随机施加，用来在「忠实反映 token 信息量」与「时序一致性」之间取平衡。</p><h2 id="§-7-—-实验设计与结论" tabindex="-1">§ 7 — 实验设计与结论 <a class="header-anchor" href="#§-7-—-实验设计与结论" aria-label="Permalink to &quot;§ 7 — 实验设计与结论&quot;">​</a></h2><p>先说清楚：<strong>这份技术报告没有与任何 baseline 的定量对比</strong>。全部定量结果只有 scaling 分析中的交叉熵，其余是定性能力展示。</p><p><strong>数据</strong>是 4,700 小时 25 Hz 的自有伦敦城区驾驶数据（2019–2023），约 4.2 亿张唯一图像。训练时按特征做平衡采样，权重与分箱后的经验分布成反比，强度指数取 0.5 作折中；tokenizer 按纬度、经度、天气类别平衡，世界模型与扩散模型额外加入转向与速度行为类别。验证集 400 小时，进一步切成「严格在验证围栏内（训练从未见过的道路）」与「主采集路线周边」两块，分别监控泛化与过拟合。训练规模为 tokenizer 200k 步 / 32 张 A100、世界模型 100k 步 / 64 张 A100 / 15 天、解码器 300k 步 / 32 张 A100。</p><p><strong>能否用小模型预测大模型？</strong> 用参数量 0.65M 到 650M（比最终模型小 10,000× 到 10×）的一系列模型在围栏验证集上测交叉熵，用幂律 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord mathnormal" style="margin-right:0.1076em;">f</span><span class="mopen">(</span><span class="mord mathnormal">x</span><span class="mclose">)</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.6667em;vertical-align:-0.0833em;"></span><span class="mord mathnormal">c</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">+</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:1.0991em;vertical-align:-0.25em;"></span><span class="mopen">(</span><span class="mord mathnormal">x</span><span class="mord">/</span><span class="mord mathnormal">a</span><span class="mclose"><span class="mclose">)</span><span class="msupsub"><span class="vlist-t"><span class="vlist-r"><span class="vlist" style="height:0.8491em;"><span style="top:-3.063em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">b</span></span></span></span></span></span></span></span></span></span></span> 拟合，算力按 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord mathnormal" style="margin-right:0.0715em;">C</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord">6</span><span class="mord mathnormal" style="margin-right:0.109em;">N</span></span></span></span> 估计。结论是：<strong>GAIA-1 的最终交叉熵可以用不到其 1/20 算力训练的模型高精度预测</strong>，且作者推断继续扩大数据与算力仍有可观提升空间。这是全文最硬的定量结果。</p><p><strong>模型学到了什么？</strong> 三类定性涌现性质：完全从想象生成数分钟稳定视频；给定同一段上下文反复采样能给出多重合理未来——让行交互（白车倒车让本车 vs 本车减速让白车）、环岛直行 vs 右转、交通密度变化；文本可指定天气与光照，动作可强制本车偏离车道，而这些错误行为<strong>在专家数据里从未出现</strong>，模型仍能预测出几何正确的对应状态，并能看到其他 agent 的真实反应（一次强制右转导致对向车辆做出规避机动）。作者据此论证模型解耦了本车动力学与周围环境，并展示了对 3D 几何的理解。<strong>局限</strong>：自回归生成尚不能实时运行，但适合并行化。</p><h2 id="§-8-—-take-aways" tabindex="-1">§ 8 — Take-aways <a class="header-anchor" href="#§-8-—-take-aways" aria-label="Permalink to &quot;§ 8 — Take-aways&quot;">​</a></h2><p><strong>5 句话版</strong>：GAIA-1 把驾驶世界建模拆成一个在离散 token 上做 next-token prediction 的 6.5B 自回归世界模型与一个把 token 渲染成高帧率视频的 2.6B 扩散解码器。tokenizer 用 DINO 蒸馏把压缩引导向语义而非高频信号，是让世界模型能学动力学的关键。视频、文本、动作三模态交错在同一条因果序列上，配合条件 dropout 使同一模型支持三种生成模式。核心定量结论是 LLM 式 scaling law 在世界建模上同样成立：用不到 1/20 算力的小模型就能高精度预测最终交叉熵。定性上模型展现出长时程结构、多重合理未来、以及对训练分布外动作的几何正确外推。</p><p><strong>3 句话版</strong>：把未来预测改写成语义 token 上的 next-token prediction，把画质交给独立的视频扩散解码器。scaling law 因此可迁移到世界建模。模型能被动作与文本细粒度控制，且能外推到专家数据中不存在的行为。</p><p><strong>1 句话版</strong>：用 LLM 的配方做驾驶世界模型——语义离散化加自回归加扩散渲染，并证明 scaling law 成立。</p><h2 id="§-9-—-最脆弱的假设" tabindex="-1">§ 9 — 最脆弱的假设 <a class="header-anchor" href="#§-9-—-最脆弱的假设" aria-label="Permalink to &quot;§ 9 — 最脆弱的假设&quot;">​</a></h2><p>最脆弱且代价最大的假设是：<strong>留出集上 next-token 交叉熵的下降，等价于世界模型对下游决策更有用。</strong> 这条假设承载了全部价值主张（加速训练与验证、当神经模拟器、解锁基于模型的策略学习），而全文唯一的定量指标就是交叉熵及其幂律拟合。</p><p>它可能不成立的理由很具体。交叉熵是逐 token 的平均量，会被大量容易预测的背景 token（天空、路面、建筑立面）主导，而决策真正关心的是少数关键事件——行人是否会踏出路缘、对向车是否会让行；这些事件在 token 层面权重极低，交叉熵可以在它们上面全错而整体指标几乎不动。更进一步，作者最想强调的能力恰恰是<strong>多重合理未来</strong>：如果未来分布真是多模态的，那么在单条真实轨迹上算的交叉熵会同时惩罚「预测了另一个同样合理的未来」和「预测错了物理」，二者无法区分。</p><p>论文提供的证据只有定性的：让行交互、规避机动的例子确实令人信服，但这些是<strong>挑选出来的样本</strong>，没有覆盖率统计，也没有与 DriveGAN、DriveDreamer 等的任何可比指标。<strong>缺的证据非常明确</strong>：一个下游任务的量化闭环，或一个把「路面 token」与「关键事件 token」分开报告的条件困惑度指标。</p><h2 id="§-10-—-最小复现实验" tabindex="-1">§ 10 — 最小复现实验 <a class="header-anchor" href="#§-10-—-最小复现实验" aria-label="Permalink to &quot;§ 10 — 最小复现实验&quot;">​</a></h2><p>不需要 4,700 小时数据也不需要 64 张 A100。取公开驾驶视频数据集的子集，训练一个小 VQ tokenizer 与一个 &lt;100M 参数的自回归世界模型（论文自己就用过 0.65M–650M 的一系列小模型，说明这个尺度可行）；训出三个交叉熵依次下降的 checkpoint；定义<strong>关键事件条件困惑度</strong>——标出含「切入」「让行」「行人穿越」的时间窗，分别计算窗内与窗外的 token 困惑度；另用冻结的中间表征训线性探针，预测未来 2 秒内是否发生上述事件。</p><p><strong>判定标准</strong>：若整体交叉熵下降的同时关键事件困惑度与探针准确率<strong>同步改善</strong>，则交叉熵是有效代理，scaling 论证可外推到效用；若整体交叉熵持续下降而关键事件指标停滞，说明模型主要在背景 token 上变好，scaling 曲线与自动驾驶价值脱钩。该实验不需要复现视频扩散解码器。</p><h2 id="§-11-—-最强反例设计" tabindex="-1">§ 11 — 最强反例设计 <a class="header-anchor" href="#§-11-—-最强反例设计" aria-label="Permalink to &quot;§ 11 — 最强反例设计&quot;">​</a></h2><p>最有力的攻击是给出对「涌现性质」的<strong>替代解释</strong>：论文归因于「理解了世界的生成规则」的现象，可能只是高容量模型在 4.2 亿张伦敦街景上做了足够好的近邻检索与插值。作者自己给了最好的靶子：强制本车偏离车道被解读为「外推到训练数据之外」，但伦敦 4,700 小时数据里必然包含大量真实的转弯、变道、绕障片段——「偏离车道」在<strong>图像分布</strong>上未必是分布外的，只是在<strong>动作-图像联合分布</strong>上被标注为专家不会做的动作。判别实验：第一组动作<strong>视觉上仍在流形内</strong>（偏离车道、急转），第二组<strong>视觉上也在流形外</strong>（强制速度为负、或曲率与速度组合到会侧滑）；预测第一组依然漂亮、第二组明显退化，若成立，「外推」的正确表述应是「在视觉流形内的动作重定向」而非「理解了动力学规则」。</p><h2 id="§-12-—-follow-up-research-idea" tabindex="-1">§ 12 — Follow-up Research Idea <a class="header-anchor" href="#§-12-—-follow-up-research-idea" aria-label="Permalink to &quot;§ 12 — Follow-up Research Idea&quot;">​</a></h2><p><strong>驱动局限</strong>：GAIA-1 的训练信号是<strong>均匀的</strong>——每个 token 的交叉熵权重相同，无论它是天空还是即将横穿马路的行人；而下游用途关心的效用分布极度不均匀。scaling law 在这样的目标下告诉你的是「预测像素分布会变好」，而非「预测重要的事会变好」。</p><p><strong>新 framing</strong>：把训练目标从「预测下一个 token」改成「<strong>预测那些会改变最优决策的 token</strong>」。这不是重加权损失这种增量改动，而是引入新的目标定义：一个 token 的价值等于知道它与不知道它之间最优策略的期望回报之差。可借鉴决策分析里的<strong>信息价值</strong>，以及主动感知与 belief-space planning 里对「哪个观测值得获取」的经典处理；实现上可用一个轻量的下游规划器作效用探针，估计每个 token 位置的决策敏感度并据此调制自回归损失权重。</p><p><strong>第一个实验</strong>：不需要重训 6.5B 模型。在 §10 的小规模设置上训练算力严格对齐的两个模型——均匀交叉熵与效用加权交叉熵。核心观测量不是整体交叉熵（后者在这个指标上<strong>预期会更差</strong>，这正是重点），而是关键事件条件困惑度、让行场景的概率校准误差、以及用各自世界模型做 rollout 的规划器碰撞率。若加权模型在整体交叉熵更差的同时下游全面更好，就证明了一件对整个世界模型领域都重要的事：<strong>交叉熵 scaling law 是一条正确但目标错位的曲线</strong>，值得为世界模型单独定义一条效用导向的 scaling law。</p>',41)])])}const d=a(e,[["render",l]]);export{o as __pageData,d as default};
